childElements.propertySetConfig:
{
  "controlWidth" : 12,
  "label" : "TextBlock1",
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\"><strong>Apologise to the customer:<br /></strong><br />&ldquo;I sincerely apologise for your experience. It sounds like our service fell short of what you were expecting as a customer.&rdquo;<br />OR<br />&ldquo;I&rsquo;m sorry about this. I am hearing we didn&rsquo;t make a good impression on you.&rdquo;<br /><br /><strong>Acknowledge feedback:<br /></strong><br />&ldquo;Thank you for raising this with us, I&rsquo;ve recorded your feedback and will include it in our regular review of how we can do things differently.&rdquo;<br />AND/OR<br />\"Please be assured that we do review complaints to ensure we maintain appropriate service levels.\"<br />AND/OR<br />\"Your complaint is reported internally to show what training and support is needed for our staff.\"</div>",
  "show" : {
    "group" : {
      "operator" : "OR",
      "rules" : [ {
        "data" : "Staff interaction complaint",
        "condition" : "=",
        "field" : "Apologise:ApologiseTalktrack:selectedButtonName"
      } ]
    }
  },
  "dataJSON" : true,
  "HTMLTemplateId" : "",
  "textKey" : "",
  "sanitize" : false
}

{
  "sanitize" : false,
