        "field" : "Confirm:ConfirmTalkTrack:selectedButtonName"
      } ]
    }
  },
  "text" : "<div style=\"font-size: 15px; border-radius: 10px; padding: 10px; height: 200px; overflow-x: hidden; overflow-y: auto; background-color: #e8e8e8;\">\n<div><span><strong>Ask further questions (if relevant) to confirm complaint details, such as:</strong></span></div>\n<div><br /><span>&ldquo;Can you tell me what your concerns were with our correspondence?&rdquo;</span></div>\n<div><span >&ldquo;I understand you weren&rsquo;t happy with our correspondence, is that right?&rdquo;</span></div>\n<div><span>&ldquo;Can you confirm when you received our correspondence and which department it was from?&rdquo;</span></div>\n</div>",
  "label" : "TextBlock1",
  "controlWidth" : 12
}

